/**
 * Applies Blutheist's Android customisations to the Capacitor-generated android/ project.
 * Idempotent: safe to run on every build. (android/ is generated by `npx cap add android`, never committed.)
 *
 *   - AndroidManifest.xml: permissions, background audio, blutheist:// links, soft-keyboard behaviour
 *   - MainActivity + the BlutheistNative permission plugin (Java)
 *   - app/build.gradle: signing, ABIs, native-lib extraction, and the asset-ignore pattern that would
 *     otherwise silently drop node_modules folders starting with "_" from the APK
 *   - variables.gradle: minSdk 24 (nodejs-mobile's floor)
 *   - launcher icons from src/assets/brand/blutheist-icon.svg, black system bars
 */
import { cpSync, existsSync, mkdirSync, readFileSync, writeFileSync, readdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { Resvg } from "@resvg/resvg-js";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const android = join(root, "android");
const app = join(android, "app");
const main = join(app, "src", "main");
const PKG = "com.blutheist.music";

if (!existsSync(app)) throw new Error("android/ not found — run `npx cap add android` first");

const read = (p) => readFileSync(p, "utf8");
const write = (p, s) => {
  mkdirSync(dirname(p), { recursive: true });
  writeFileSync(p, s);
};

/* ------------------------------------------------------------------ manifest */
{
  const p = join(main, "AndroidManifest.xml");
  let x = read(p);

  const perms = [
    ["android.permission.INTERNET"],
    ["android.permission.ACCESS_NETWORK_STATE"],
    ["android.permission.WAKE_LOCK"],
    ["android.permission.FOREGROUND_SERVICE"],
    ["android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK"],
    ["android.permission.POST_NOTIFICATIONS"],
    ["android.permission.READ_MEDIA_AUDIO"],
    ["android.permission.READ_EXTERNAL_STORAGE", 'android:maxSdkVersion="32"'],
    ["android.permission.WRITE_EXTERNAL_STORAGE", 'android:maxSdkVersion="28"'],
  ];
  const have = (name) => x.includes(`android:name="${name}"`);
  const add = perms
    .filter(([n]) => !have(n))
    .map(([n, extra]) => `    <uses-permission android:name="${n}"${extra ? " " + extra : ""} />`)
    .join("\n");
  if (add) x = x.replace(/<\/manifest>\s*$/, `\n${add}\n</manifest>\n`);

  const setAppAttr = (name, value) => {
    const re = new RegExp(`(<application\\b[^>]*?)\\s${name.replace(":", "\\:")}="[^"]*"`);
    if (re.test(x)) x = x.replace(re, `$1 ${name}="${value}"`);
    else x = x.replace(/<application\b/, `<application ${name}="${value}"`);
  };
  setAppAttr("android:usesCleartextTraffic", "true"); // the loopback stream server is plain http://127.0.0.1
  setAppAttr("android:largeHeap", "true");
  setAppAttr("android:hardwareAccelerated", "true");

  const setActAttr = (name, value) => {
    const re = new RegExp(`(<activity\\b[^>]*?)\\s${name.replace(":", "\\:")}="[^"]*"`);
    if (re.test(x)) x = x.replace(re, `$1 ${name}="${value}"`);
    else x = x.replace(/<activity\b/, `<activity ${name}="${value}"`);
  };
  setActAttr("android:windowSoftInputMode", "adjustResize");
  setActAttr("android:launchMode", "singleTask");

  if (!x.includes('android:scheme="blutheist"')) {
    x = x.replace(
      /(<activity\b[\s\S]*?)(<\/activity>)/,
      `$1    <intent-filter>
                <action android:name="android.intent.action.VIEW" />
                <category android:name="android.intent.category.DEFAULT" />
                <category android:name="android.intent.category.BROWSABLE" />
                <data android:scheme="blutheist" />
            </intent-filter>
        $2`
    );
  }
  write(p, x);
}

/* ------------------------------------------------------------------ Java */
{
  const dir = join(main, "java", ...PKG.split("."));
  mkdirSync(dir, { recursive: true });
  cpSync(join(root, "scripts/android/native/BlutheistNative.java"), join(dir, "BlutheistNative.java"));
  cpSync(join(root, "scripts/android/native/MainActivity.java"), join(dir, "MainActivity.java"));
}

/* ------------------------------------------------------------------ gradle */
{
  const vars = join(android, "variables.gradle");
  if (existsSync(vars)) {
    let v = read(vars);
    v = v.replace(/minSdkVersion\s*=\s*(\d+)/, (m, n) => (Number(n) < 24 ? "minSdkVersion = 24" : m));
    write(vars, v);
  }

  const gp = join(app, "build.gradle");
  let g = read(gp);
  const MARK = "// ---- Blutheist customisations ----";
  if (!g.includes(MARK)) {
    g += `
${MARK}
android {
    signingConfigs {
        blutheist {
            storeFile file(System.getenv("ANDROID_KEYSTORE_PATH") ?: "../../scripts/android/blutheist-sideload.jks")
            storePassword System.getenv("ANDROID_KEYSTORE_PASSWORD") ?: "blutheist-sideload"
            keyAlias System.getenv("ANDROID_KEY_ALIAS") ?: "blutheist"
            keyPassword System.getenv("ANDROID_KEY_PASSWORD") ?: "blutheist-sideload"
        }
    }
    defaultConfig {
        ndk {
            abiFilters "arm64-v8a", "armeabi-v7a", "x86_64"
        }
    }
    buildTypes {
        release {
            signingConfig signingConfigs.blutheist
            minifyEnabled false
            shrinkResources false
        }
        debug {
            signingConfig signingConfigs.blutheist
        }
    }
    packagingOptions {
        jniLibs {
            useLegacyPackaging = true
        }
    }
    // The default pattern skips any asset directory beginning with "_" — it would silently delete
    // parts of node_modules (jsdom's dependencies) from the embedded Node project.
    aaptOptions {
        ignoreAssetsPattern '!.svn:!.git:!.ds_store:!*.scc:!CVS:!thumbs.db:!picasa.ini:!*~'
    }
}
`;
    write(gp, g);
  }
}

/* ------------------------------------------------------------------ icons + system bars */
{
  const svgPath = join(root, "src/assets/brand/blutheist-icon.svg");
  const svg = read(svgPath);
  const render = (size) =>
    new Resvg(svg, { fitTo: { mode: "width", value: size }, background: "rgba(0,0,0,0)", font: { loadSystemFonts: false } }).render().asPng();

  const dens = { mdpi: 48, hdpi: 72, xhdpi: 96, xxhdpi: 144, xxxhdpi: 192 };
  for (const [d, px] of Object.entries(dens)) {
    const dir = join(main, "res", `mipmap-${d}`);
    mkdirSync(dir, { recursive: true });
    const png = render(px);
    writeFileSync(join(dir, "ic_launcher.png"), png);
    writeFileSync(join(dir, "ic_launcher_round.png"), png);
    // Adaptive icon foreground: 108dp canvas, artwork inside the central 66% safe zone.
    const canvas = Math.round((px / 48) * 108);
    const inner = Math.round(canvas * 0.62);
    const innerB64 = Buffer.from(render(inner)).toString("base64");
    const off = Math.round((canvas - inner) / 2);
    const fg = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${canvas}" height="${canvas}" viewBox="0 0 ${canvas} ${canvas}"><image x="${off}" y="${off}" width="${inner}" height="${inner}" xlink:href="data:image/png;base64,${innerB64}"/></svg>`;
    writeFileSync(join(dir, "ic_launcher_foreground.png"), new Resvg(fg, { background: "rgba(0,0,0,0)" }).render().asPng());
  }
  write(
    join(main, "res", "mipmap-anydpi-v26", "ic_launcher.xml"),
    `<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@color/ic_launcher_background"/>
    <foreground android:drawable="@mipmap/ic_launcher_foreground"/>
</adaptive-icon>
`
  );
  write(
    join(main, "res", "mipmap-anydpi-v26", "ic_launcher_round.xml"),
    `<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@color/ic_launcher_background"/>
    <foreground android:drawable="@mipmap/ic_launcher_foreground"/>
</adaptive-icon>
`
  );
  write(
    join(main, "res", "values", "ic_launcher_background.xml"),
    `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="ic_launcher_background">#0B0B10</color>
</resources>
`
  );

  // Black status/navigation bars and window background (no white flash before the page paints).
  const sp = join(main, "res", "values", "styles.xml");
  if (existsSync(sp)) {
    let s = read(sp);
    const items = `
        <item name="android:windowBackground">#000000</item>
        <item name="android:statusBarColor">#000000</item>
        <item name="android:navigationBarColor">#000000</item>`;
    if (!s.includes("Blutheist-bars")) {
      s = s.replace(/(<style name="AppTheme\.NoActionBar"[^>]*>)/, `$1\n        <!-- Blutheist-bars -->${items}`);
      s = s.replace(/(<style name="AppTheme\.NoActionBarLaunch"[^>]*>)/, `$1\n        <item name="android:windowBackground">#000000</item>`);
      write(sp, s);
    }
  }
}

console.log("[android] patched android/ for Blutheist");
void readdirSync;
